    26	# Agents sometimes keep the template's TSX convention and sometimes emit JSX
    27	# from .js/.ts modules.  Scan all four source suffixes so the delivery check does
    28	# not silently miss an unnamed control because of the chosen extension.
    29	JSX_SUFFIXES = (".tsx", ".jsx", ".ts", ".js")
    30	SKIPPED_TYPES = {"hidden", "submit", "button", "reset", "image"}
    31	_CONTROL_OPEN = re.compile(r"<(input|select|textarea)\b")
    32	_LABEL_TAG = re.compile(r"<label\b|</label\s*>")
    33	_COMPONENT_TAG = re.compile(r"<([A-Z][\w.]*)\b|</([A-Z][\w.]*)\s*>")
    34	_COMPONENT_DEF = re.compile(
    35	    r"^[ \t]*(?:export\s+)?(?:default\s+)?(?:function\s+([A-Z]\w*)\s*[(<]|const\s+([A-Z]\w*)\s*(?::[^=\n]+)?=\s*)",
    36	    re.M,
    37	)
    38	_ATTR_VALUE = r"""\s*=\s*(?:"([^"]*)"|'([^']*)'|\{([^{}]*(?:\{[^{}]*\}[^{}]*)*)\})"""
    39	_ID_ATTR = re.compile(r"(?<![\w-])id" + _ATTR_VALUE)
    40	_HTMLFOR_ATTR = re.compile(r"\bhtmlFor" + _ATTR_VALUE)
    41	_TYPE_ATTR = re.compile(r"""(?<![\w-])type\s*=\s*(?:["']([^"']*)["']|\{\s*["']([^"']*)["']\s*\})""")
    42	_ARIA_NAME = re.compile(r"\baria-label(?:ledby)?\s*=")
    43	_SPREAD = re.compile(r"\{\s*\.\.\.")
    44	_CHILDREN = re.compile(r"\{\s*(?:props\.)?children\s*\}")
    45	_CONTROL_IN = re.compile(r"<(?:input|select|textarea)\b")
    46	_BACKTICK = re.compile(r"`([^`\n]+)`")
    47	_PLACEHOLDER = re.compile(r"<[^<>\n]{1,60}>")
    48	_SENTENCE_SPLIT = re.compile(r"(?<=[.;])\s+(?=[A-Z])")
    49	_SEED_SENTENCE = re.compile(r"\bseed", re.I)
    50	_RANGE_REFERENCE = re.compile(r"[A-Z]{1,3}\d+:[A-Z]{1,3}\d+")  # a position such as B2:D9, not a value
    51	_VALUE_PARTS = re.compile(r"[/=:]")
    52	_WORD = re.compile(r"[A-Za-z][A-Za-z-]*")
    53	_SLUG = re.compile(r"[A-Za-z0-9][A-Za-z0-9._-]*")
    54	_OWNER_NAME = re.compile(r"([A-Za-z0-9][A-Za-z0-9._-]*)/([A-Za-z0-9][A-Za-z0-9._-]*)")
    55	_ACCOUNT_NOUNS = {"account", "accounts", "user", "users", "username", "login", "handle"}
    56	_PASSWORD_NOUNS = {"password", "passwords", "passphrase", "passcode"}
    57	_OWNER_NOUNS = {"owner", "owners"}
    58	_PERSON_NOUNS = _ACCOUNT_NOUNS | _PASSWORD_NOUNS | _OWNER_NOUNS | {
    59	    "email", "e-mail", "emails", "member", "members", "reviewer", "reviewers", "maintainer", "maintainers",
    60	    "admin", "admins", "administrator", "administrators", "collaborator", "collaborators", "author", "authors",
    61	    "assignee", "assignees",
