    65	def _skip_string(text: str, index: int) -> int:
    66	    quote = text[index]
    67	    index += 1
    68	    while index < len(text):
    69	        if text[index] == "\\":
    70	            index += 2
    71	            continue
    72	        if text[index] == quote:
    73	            return index + 1
    74	        index += 1
    75	    return len(text)
    76	
    77	
    78	def _tag_end(text: str, start: int) -> int | None:
    79	    """Index just past the '>' that closes the JSX opening tag at text[start] == '<'."""
    80	    depth = 0
    81	    index = start + 1
    82	    while index < len(text):
    83	        char = text[index]
    84	        if char in "\"'`" and (depth > 0 or char != "`"):
    85	            index = _skip_string(text, index)
    86	            continue
    87	        if char == "{":
    88	            depth += 1
    89	        elif char == "}":
    90	            depth = max(0, depth - 1)
    91	        elif depth == 0 and char == ">":
    92	            return index + 1
    93	        elif depth == 0 and char == "<":
    94	            return None
    95	        index += 1
    96	    return None
