   104	def _intervals(text: str, pattern: re.Pattern[str], name_of: Any) -> list[tuple[str, int, int]]:
   105	    """(name, open start, close end) for container elements; self-closing and unmatched tags are ignored."""
   106	    stacks: dict[str, list[int]] = {}
   107	    found: list[tuple[str, int, int]] = []
   108	    for match in pattern.finditer(text):
   109	        name, closing = name_of(match)
   110	        if closing:
   111	            if stacks.get(name):
   112	                found.append((name, stacks[name].pop(), match.end()))
   113	            continue
   114	        end = _tag_end(text, match.start())
   115	        if end is not None and not text[:end].rstrip().endswith("/>"):
   116	            stacks.setdefault(name, []).append(match.start())
   117	    return found
   118	
