   120	def _label_intervals(text: str) -> list[tuple[str, int, int]]:
   121	    return _intervals(text, _LABEL_TAG, lambda m: ("label", m.group(0).startswith("</")))
   122	
   123	
   124	def _component_intervals(text: str) -> list[tuple[str, int, int]]:
   125	    return _intervals(text, _COMPONENT_TAG, lambda m: (m.group(1) or m.group(2), m.group(2) is not None))
   126	
   127	
   128	def _component_bodies(text: str) -> list[tuple[str, int, int]]:
   129	    starts = [(m.group(1) or m.group(2), m.start()) for m in _COMPONENT_DEF.finditer(text)]
   130	    return [(name, start, starts[i + 1][1] if i + 1 < len(starts) else len(text)) for i, (name, start) in enumerate(starts)]
   131	
   132	
   133	def _line(text: str, index: int) -> int:
   134	    return text.count("\n", 0, index) + 1
