   137	def _frontend_files(frontend_src: Path) -> list[Path]:
   138	    files: list[Path] = []
   139	    for dirpath, dirnames, filenames in os.walk(frontend_src):
   140	        dirnames[:] = [d for d in dirnames if d not in {"node_modules", "dist", "build"} and not d.startswith(".")]
   141	        files.extend(Path(dirpath) / name for name in filenames
   142	                     if name.endswith(JSX_SUFFIXES) and not re.search(r"\.(test|spec)\.", name))
   143	    return sorted(files)
