   146	def _classify_components(sources: dict[Path, str]) -> tuple[set[str], list[dict[str, Any]]]:
   147	    """Field components that name the control they are given, and shared field components whose <label>
   148	    names nothing (a label without htmlFor, filled from a prop, next to a control or {children})."""
   149	    providers: set[str] = set()
   150	    broken: list[dict[str, Any]] = []
   151	    for path, text in sources.items():
   152	        for name, start, end in _component_bodies(text):
   153	            body = text[start:end]
   154	            labels = _label_intervals(body)
   155	            renders_children = bool(_CHILDREN.search(body))
   156	            wraps = any(_CHILDREN.search(body[s:e]) for _, s, e in labels)
   157	            injects_id = "htmlFor" in body and ("cloneElement" in body or "useId" in body) and renders_children
   158	            if wraps or injects_id:
   159	                providers.add(name)
   160	                continue
   161	            for _, label_start, label_end in labels:
   162	                open_end = _tag_end(body, label_start) or label_start
   163	                attrs, inner = body[label_start:open_end], body[open_end:label_end]
   164	                outside = body[:label_start] + body[label_end:]
   165	                if ("htmlFor" not in attrs and "{" in inner and not _CONTROL_IN.search(inner)
   166	                        and (_CONTROL_IN.search(outside) or _CHILDREN.search(outside))):
   167	                    broken.append({"file": str(path), "line": _line(text, start + label_start),
   168	                                   "tag": "label", "component": name})
   169	                    break
   170	    return providers, broken
   171	
