   173	def label_check(frontend_src: Path, root: Path | None = None) -> dict[str, Any]:
   174	    """Controls without an accessible name, plus shared field components whose label names nothing."""
   175	    root = root or frontend_src
   176	    sources = {path: path.read_text(encoding="utf-8", errors="ignore") for path in _frontend_files(frontend_src)}
   177	    providers, broken = _classify_components(sources)
   178	    static_for = {_value(m) for text in sources.values() for m in _HTMLFOR_ATTR.finditer(text)
   179	                  if m.group(1) is not None or m.group(2) is not None}
   180	    controls = 0
   181	    problems: list[dict[str, Any]] = []
   182	    for path, text in sources.items():
   183	        file_for = {_value(m) for m in _HTMLFOR_ATTR.finditer(text)}
   184	        labels = _label_intervals(text)
   185	        containers = [(s, e) for name, s, e in _component_intervals(text) if name in providers]
   186	        for match in _CONTROL_OPEN.finditer(text):
   187	            end = _tag_end(text, match.start())
   188	            if end is None:
   189	                continue
   190	            attrs = text[match.start():end]
   191	            type_match = _TYPE_ATTR.search(attrs)
   192	            if type_match and (type_match.group(1) or type_match.group(2) or "").lower() in SKIPPED_TYPES:
   193	                continue
   194	            controls += 1
   195	            position = match.start()
   196	            id_match = _ID_ATTR.search(attrs)
   197	            named = (
   198	                bool(_ARIA_NAME.search(attrs))
   199	                or bool(_SPREAD.search(attrs))  # props come from the caller: cannot tell statically
   200	                or (id_match is not None and (_value(id_match) in file_for or _value(id_match) in static_for))
   201	                or any(s < position < e for _, s, e in labels)
   202	                or any(s < position < e for s, e in containers)
   203	            )
   204	            if not named:
   205	                problems.append({"file": str(path), "line": _line(text, position), "tag": match.group(1)})
   206	    for item in broken + problems:
   207	        item["file"] = os.path.relpath(item["file"], root)
   208	    ordered = broken + problems
   209	    return {"controls": controls, "unnamed": len(ordered), "problems": ordered,
   210	            "components": [f"{b['component']} ({b['file']}:{b['line']})" for b in broken]}
