   213	def _seed_sentences(document: Any) -> list[tuple[str, str]]:
   214	    """(requirement id, sentence) for every seed-like scenario GIVEN precondition, in document order."""
   215	    sentences: list[tuple[str, str]] = []
   216	
   217	    def visit(node: Any) -> None:
   218	        if not isinstance(node, dict):
   219	            return
   220	        req_id = str(node.get("id") or node.get("req_id") or "").strip() or "ROOT"
   221	        for scenario in node.get("scenarios") or []:
   222	            for step in (scenario or {}).get("steps") or [] if isinstance(scenario, dict) else []:
   223	                if not isinstance(step, dict):
   224	                    continue
   225	                if str(step.get("keyword") or step.get("type") or "").strip().upper() != "GIVEN":
   226	                    continue
   227	                content = str(step.get("content") or step.get("text") or "")
   228	                # A GIVEN step is itself a precondition.  Many ARC tasks say "a repository
   229	                # `owner/name` exists" or "cell `A1=42`" without using the literal word
   230	                # "seed"; limiting extraction to that word drops exactly the structured
   231	                # fixtures used by spreadsheet and GitHub-style tasks.
   232	                parts = _SENTENCE_SPLIT.split(content)
   233	                sentences.extend((req_id, sentence) for sentence in parts
   234	                                 if _SEED_SENTENCE.search(sentence) or _BACKTICK.search(sentence))
   235	        for child in node.get("children") or node.get("requirements") or []:
   236	            visit(child)
   237	
   238	    visit(document)
   239	    return sentences
   240	
