   242	def seed_values(document: Any) -> list[dict[str, Any]]:
   243	    """Concrete fixtures that the scenarios state must exist before a test.
   244	
   245	    Values described as unknown, unused, or absent are deliberately excluded;
   246	    they are returned by :func:`forbidden_seed_values` instead.
   247	    """
   248	    values = compile_manifest(document)["fixtures"]["must_exist"]
   249	    return [item for item in values if not _RANGE_REFERENCE.fullmatch(item["text"])]
   250	
   251	
   252	def forbidden_seed_values(document: Any) -> list[dict[str, Any]]:
   253	    """Values that negative preconditions require to remain absent from startup seed data."""
   254	    return compile_manifest(document)["fixtures"]["must_not_exist"]
   255	
   256	
   257	def _seed_items(sentence: str) -> list[dict[str, Any]]:
   258	    """Each backtick value of a seed sentence with the noun that introduces it (the last word before it;
   259	    "owned by" counts as "owner") and up to two qualifier words before that noun ("public", "private", ...).
   260	    A value preceded only by "and", "or" or a comma keeps the previous value's noun and qualifiers."""
   261	    items: list[dict[str, Any]] = []
   262	    noun, qualifiers, last = "", [], 0
   263	    for match in _BACKTICK.finditer(sentence):
   264	        words = [word.lower() for word in _WORD.findall(sentence[last:match.start()])]
   265	        if words and words[-1] not in {"and", "or"}:
   266	            if words[-2:] == ["owned", "by"]:
   267	                noun, qualifiers = "owner", words[-4:-2]
   268	            else:
   269	                noun, qualifiers = words[-1], words[-3:-1]
   270	        items.append({"noun": noun, "qualifiers": qualifiers, "value": match.group(1).strip()})
   271	        last = match.end()
   272	    return items
   273	
