   275	def seed_account(document: Any) -> dict[str, Any] | None:
   276	    """The first seeded account (document order) that a seed sentence gives a password for:
   277	    {"username", "email", "password", "id"}, or None when no seed sentence names a password."""
   278	    forbidden = {item["text"] for item in forbidden_seed_values(document)}
   279	    for req_id, sentence in _seed_sentences(document):
   280	        items = [item for item in _seed_items(sentence) if item["value"] and not _PLACEHOLDER.search(item["value"])]
   281	        password = next((item["value"] for item in items if item["noun"] in _PASSWORD_NOUNS), None)
   282	        if not password or password in forbidden:
   283	            continue
   284	        email = next((item["value"] for item in items if "@" in item["value"] and item["value"] not in forbidden), None)
   285	        username = next((item["value"] for item in items
   286	                         if item["noun"] in _ACCOUNT_NOUNS and "@" not in item["value"]
   287	                         and item["value"] not in forbidden), None)
   288	        if username or email:
   289	            return {"username": username or email, "email": email, "password": password, "id": req_id}
   290	    return None
