   298	def public_prerequisites(document: Any) -> dict[str, Any]:
   299	    """Select bounded GitHub prerequisite flows from the supplied public tree.
   300	
   301	    The returned configuration is inert for other task families.  Values come
   302	    from GIVEN steps rather than hard-coded benchmark fixtures.
   303	    """
   304	    nodes: list[dict[str, Any]] = []
   305	
   306	    def visit(node: Any) -> None:
   307	        if not isinstance(node, dict):
   308	            return
   309	        nodes.append(node)
   310	        for child in node.get("children") or node.get("requirements") or []:
   311	            visit(child)
   312	
   313	    if isinstance(document, list):
   314	        for node in document:
   315	            visit(node)
   316	    else:
   317	        visit(document)
   318	    descriptions = "\n".join(str(node.get("description") or "") for node in nodes)
   319	    config: dict[str, Any] = {
   320	        "kind": "none",
   321	        "evidence_kind": "public_prerequisites_not_full_acceptance",
   322	    }
   323	    markers = ("Username or email", "Agree to the terms", "Send reset link", "Invalid credentials")
   324	    if not all(marker in descriptions for marker in markers):
   325	        return config
   326	
   327	    config["kind"] = "github"
   328	    sign_in = next((node for node in nodes if node.get("name") == "Sign In with an Existing Account"), {})
   329	    search = next((node for node in nodes if node.get("name") == "Search for and Locate Repositories"), {})
