   356	def _backend_corpus(backend_src: Path) -> str:
   357	    parts: list[str] = []
   358	    for dirpath, dirnames, filenames in os.walk(backend_src):
   359	        dirnames[:] = [d for d in dirnames if d != "node_modules" and not d.startswith(".")]
   360	        for name in filenames:
   361	            path = Path(dirpath) / name
   362	            try:
   363	                if path.stat().st_size <= 2_000_000:
   364	                    parts.append(path.read_text(encoding="utf-8", errors="ignore"))
   365	            except OSError:
   366	                continue
   367	    return "\n".join(parts)
