   370	def _present(text: str, corpus: str) -> tuple[bool, bool]:
   371	    """(present, present only as parts). Case-sensitive. A value with spaces must be a whole string
   372	    literal, so a renamed or suffixed title does not count; a formula must appear as written; a compound
   373	    value such as `name/number` or `cell=value` also counts when each of its parts appears."""
   374	    quoted = lambda value: bool(re.search(r"(['\"`])" + re.escape(value) + r"\1", corpus))
   375	    if re.search(r"\s", text) or text.startswith("="):
   376	        return quoted(text), False
   377	    if quoted(text):
   378	        return True, False
   379	    parts = [part for part in _VALUE_PARTS.split(text) if part.strip()]
   380	    if len(parts) > 1 and all(quoted(part) for part in parts):
   381	        return True, True
   382	    return text in corpus, False
   383	
   384	
   385	def is_notation(text: str) -> bool:
   386	    """A compound notation such as `name/number`, `cell=value` or a formula: it describes structured
   387	    content (often a per-scenario starting state) rather than a string to copy, so it is reported but
   388	    not handed to an automatic repair."""
   389	    return bool(_VALUE_PARTS.search(text))
