   392	def seed_text_check(
   393	    backend_src: Path,
   394	    values: list[dict[str, Any]],
   395	    forbidden: list[dict[str, Any]] | None = None,
   396	) -> dict[str, Any]:
   397	    corpus = _backend_corpus(backend_src)
   398	    missing: list[dict[str, Any]] = []
   399	    by_parts = 0
   400	    for item in values:
   401	        present, parts_only = _present(item["text"], corpus)
   402	        if not present:
   403	            missing.append(item)
   404	        by_parts += int(parts_only)
   405	    seed_file = backend_src / "database" / "seed_db.js"
   406	    seed_corpus = seed_file.read_text(encoding="utf-8", errors="ignore") if seed_file.is_file() else ""
   407	    forbidden_present = []
   408	    for item in forbidden or []:
   409	        present, _parts_only = _present(item["text"], seed_corpus)
   410	        if present:
   411	            forbidden_present.append(item)
   412	    failing = [dict(item, kind="missing_required") for item in missing]
   413	    failing.extend(dict(item, kind="forbidden_present") for item in forbidden_present)
   414	    return {
   415	        "total": len(values),
   416	        "found": len(values) - len(missing),
   417	        "found_by_parts": by_parts,
   418	        "missing": missing,
   419	        "forbidden_total": len(forbidden or []),
   420	        "forbidden_present": forbidden_present,
     1	"""Behavior contract: the gestures, keyboard shortcuts and ARIA states a requirements yaml declares, read at
     2	run time for the self-check's browser probe (arc_behavior_probe.js). No task-specific string lives here: every
     3	name, role and state comes from the yaml; the only built-in knowledge is the ARIA role vocabulary and a few
     4	English phrases that map to it.
     5	
     6	behavior_contract(document) -> {"entry", "coordinates", "checks": [...]}; each check is one declared behavior:
     7	  selected_on_open    right after the entry opens, an element of the role that an aria-selected="true" sentence
     8	                      calls current/active is selected (exactly one for tabs)
     9	  multiselectable     the element with the grid role (and the quoted name, if the sentence gives one) exposes
    10	                      aria-multiselectable="true"
    11	  click_select        clicking an element of the role selects it and only it
    12	  drag_select         dragging from one corner to the opposite one selects exactly that rectangle
    13	  selection_persists  the dragged rectangle is still selected after a reload
    14	  tab_switch          clicking another tab makes it the selected tab at once
    15	  editor_gesture      double-clicking an element shows the text box the sentence names
    16	  commit_key          in that text box, the key commits: the new text shows at once
    17	  commit_click_other  clicking another element commits: the new text shows at once
    18	  cancel_key          the key cancels: the old text stays
    19	  commit_persists     a committed text is still shown after a reload
    20	  context_menu        right-clicking an element opens a menu with menuitem commands (a named one, if given)
    21	  key_same_as         a keyboard shortcut does what the named control does
    22	Standard library only.
    23	"""
    24	
    25	from __future__ import annotations
    26	
    27	import re
    28	from collections import Counter
    29	from typing import Any
    30	
    31	from arc_requirement_manifest import is_placeholder_text
    32	
    33	_SENTENCE = re.compile(r"(?<=[.;])\s+")
    34	_QUOTED = re.compile(r'"([^"]{1,90})"')
    35	_ENTRY = re.compile(r"\bseeded\s+(\w+)\s+`([^`]+)`")
    36	_KEY = re.compile(r"\b(Ctrl|Control|Cmd|Command|Meta)\s*\+\s*([A-Za-z0-9])\b")
    37	_SELF_ROLE = re.compile(r"\b(tab|gridcell|row|option|treeitem|menuitem)\b")
    38	# nouns a sentence uses for things with an ARIA role; a noun counts only when the yaml prescribes that role
    39	_NOUN_ROLE = (
    40	    (r"grid cells?|cells?", "gridcell"),
    41	    (r"row numbers?|row headers?", "rowheader"),
    42	    (r"column headers?|column letters?", "columnheader"),
    43	    (r"tabs?", "tab"),
    44	    (r"options?", "option"),
    45	    (r"rows?", "row"),
    46	)
    47	# accessible-name shapes a sentence prescribes for a role ("gridcell role with their cell coordinates")
    48	_NAME_SHAPES = (
    49	    ("gridcell", re.compile(r"\bgridcell\b[^.;]*\bcell coordinates?\b|\bcell coordinates?\b[^.;]*\bgridcell\b"), r"^[A-Z]{1,3}[0-9]+$"),
    50	    ("rowheader", re.compile(r"\browheader\b[^.;]*\b(?:decimal )?row numbers?\b|\brow numbers?\b[^.;]*\browheader\b"), r"^[0-9]+$"),
    51	    ("columnheader", re.compile(r"\bcolumnheader\b[^.;]*\bcolumn letters?\b|\bcolumn letters?\b[^.;]*\bcolumnheader\b"), r"^[A-Z]{1,3}$"),
    52	)
    53	
    54	
    55	def _names(text: str) -> list[str]:
    56	    """Quoted names in a sentence, without attribute values such as aria-selected="true"."""
    57	    return [match.group(1) for match in _QUOTED.finditer(text) if not text[:match.start()].endswith("=")]
    58	
    59	
    60	def _nodes(document: Any) -> list[dict[str, Any]]:
    61	    found: list[dict[str, Any]] = []
    62	
    63	    def visit(node: Any) -> None:
    64	        if isinstance(node, dict):
    65	            found.append(node)
    66	            for child in node.get("children") or node.get("requirements") or []:
    67	                visit(child)
    68	
    69	    visit(document)
    70	    return found
    71	
    72	
    73	def _text(value: Any) -> str:
    74	    return re.sub(r"\s+", " ", str(value or "")).replace("“", '"').replace("”", '"').strip()
    75	
    76	
    77	def _behavior_text(node: dict[str, Any]) -> str:
    78	    """Text that can declare observable behavior for one requirement.
    79	
    80	    ARC tasks commonly put the normative ARIA wording in ``description`` but put the
    81	    actual gesture and expected result in scenario WHEN/THEN steps.  Treat both as
    82	    contract input while keeping the requirement id attached to every extracted check.
    83	    """
    84	    parts = [_text(node.get("description") or node.get("text"))]
    85	    for scenario in node.get("scenarios") or []:
    86	        if not isinstance(scenario, dict):
    87	            continue
    88	        scenario_parts = [_text(scenario.get("name"))]
    89	        scenario_parts.extend(
    90	            _text(step.get("content") or step.get("text"))
    91	            for step in scenario.get("steps") or []
    92	            if isinstance(step, dict)
    93	        )
    94	        if is_placeholder_text(" ".join(scenario_parts)):
    95	            continue
    96	        for step in scenario.get("steps") or []:
    97	            if isinstance(step, dict):
    98	                parts.append(_text(step.get("content") or step.get("text")))
    99	            elif isinstance(step, str):
   100	                parts.append(_text(step))
   101	    return ". ".join(part for part in parts if part)
