   103	
   104	def _role_of(noun: str, prescribed: set[str]) -> str | None:
   105	    noun = noun.strip().lower()
   106	    for pattern, role in _NOUN_ROLE:
   107	        if re.fullmatch(pattern, noun) and role in prescribed:
   108	            return role
   109	    return noun if noun in prescribed else None
