   112	def _entry(document: Any) -> dict[str, Any] | None:
   113	    votes: Counter[tuple[str, str]] = Counter()
   114	    for node in _nodes(document):
   115	        for scenario in node.get("scenarios") or []:
   116	            for step in (scenario or {}).get("steps") or [] if isinstance(scenario, dict) else []:
   117	                if isinstance(step, dict) and str(step.get("keyword") or "").upper() == "GIVEN":
   118	                    for kind, name in _ENTRY.findall(_text(step.get("content") or step.get("text"))):
   119	                        votes[(kind, name)] += 1
   120	    if not votes:
   121	        return None
   122	    (kind, name), count = votes.most_common(1)[0]
   123	    return {"kind": kind, "name": name, "scenarios": count}
   124	
   125	
   126	def behavior_contract(document: Any) -> dict[str, Any]:
   127	    nodes = [node for node in _nodes(document) if _behavior_text(node)]
   128	    whole = " ".join(_behavior_text(node) for node in nodes)
   129	    prescribed = set(re.findall(r"\b(gridcell|rowheader|columnheader|menuitem|option|treeitem)\b", whole))
   130	    prescribed |= {role for role in ("tab", "grid", "row") if re.search(rf"\bARIA {role} role\b|\b{role} role\b", whole)}
   131	    checks: list[dict[str, Any]] = []
   132	    seen: set[str] = set()
   133	
   134	    def add(kind: str, req: str, sentence: str, **fields: Any) -> None:
   135	        key = kind + repr(sorted(fields.items()))
   136	        if key in seen:
   137	            return
   138	        seen.add(key)
   139	        checks.append({"kind": kind, "req": req, "sentence": sentence[:300], **fields})
   140	
   141	    selectable: set[str] = set()
   142	    editor: dict[str, Any] | None = None
   143	    for node in nodes:
   144	        req = str(node.get("id") or node.get("req_id") or "")
   145	        sentences = _SENTENCE.split(_behavior_text(node))
   146	        for index, sentence in enumerate(sentences):
   147	            lower = sentence.lower()
   148	            # ---- ARIA states
   149	            if 'aria-selected="true"' in sentence:
   150	                roles = {role for role in _SELF_ROLE.findall(sentence) if role in prescribed}
   151	                roles |= {role for noun in re.findall(r"\b(?:current|active|every|each)\s+([a-z]+(?: [a-z]+)?)", sentence)
   152	                          for role in [_role_of(noun, prescribed) or _role_of(noun.split()[0], prescribed)] if role}
   153	                selectable |= roles
   154	                if re.search(r"\b(?:current|active)\b", lower):
   155	                    for role in sorted(roles):
   156	                        add("selected_on_open", req, sentence, role=role, exactly_one=role == "tab")
   157	            if ('aria-multiselectable="true"' in sentence and "grid" in prescribed and re.search(r"\bgrid\b", lower)
   158	                    and not any(check["kind"] == "multiselectable" for check in checks)):
   159	                names = _names(sentence)
   160	                add("multiselectable", req, sentence, role="grid", name=names[0] if names else None)
   161	            # ---- selection gestures
   162	            match = re.search(r"\bclick(?:s|ing)?\s+to\s+select\s+(?:a\s+)?(?:single\s+)?([a-z]+(?: [a-z]+)?)", sentence)
   163	            if not match:
   164	                match = re.search(r"\bclick(?:s|ing)?\s+(?:on\s+)?(?:a\s+)?([a-z]+(?: [a-z]+)?)\s+selects?\b", sentence)
   165	            if match:
   166	                role = _role_of(match.group(1), prescribed) or _role_of(match.group(1).split()[0], prescribed)
   167	                if role:
   168	                    add("click_select", req, sentence, role=role)
   169	                    if re.search(r"\bdrag(?:s|ging)?\s+from\s+one\s+corner\b", lower):
   170	                        add("drag_select", req, sentence, role=role)
   171	            if ("gridcell" in prescribed and re.search(
   172	                    r"\bdrag(?:s|ging)?\s+from\s+one\s+(?:cell|corner)\b[^.;]*\b(?:opposite|another)\s+(?:cell|corner)\b",
   173	                    lower)):
   174	                add("drag_select", req, sentence, role="gridcell")
   175	            if re.search(r"\bpersist[^.;]*\b(?:rectangle|selection)\b", lower) and re.search(r"\b(?:refresh|reload|reopen)", lower):
   176	                add("selection_persists", req, sentence, role="gridcell")
   177	            if re.search(r"\bclicks?\s+(?:on\s+)?(?:another|a different)\s+(?:aria\s+)?tab\b", lower) and "tab" in prescribed:
   178	                add("tab_switch", req, sentence, role="tab")
   179	            # ---- inline editor
   180	            match = re.search(r"\bdouble-click(?:s|ing)?\s+(?:a |an |the )?([a-z ]+?)\s+(?:displays|shows|opens)\s+"
   181	                              r"(?:an?\s+)?(?:inline\s+)?text\s*box\s+with\s+the\s+accessible\s+name\s+\"([^\"]+)\"", sentence, re.I)
   182	            if match and _role_of(match.group(1), prescribed):
   183	                editor = {"on": _role_of(match.group(1), prescribed), "name": match.group(2)}
   184	                add("editor_gesture", req, sentence, **editor)
   185	            match = re.search(r"\bpress(?:es|ing)?\s+(Enter|Return|Tab)\s+(?:or\s+click(?:s|ing)?\s+(?:on\s+)?another\s+([a-z]+(?: [a-z]+)?)\s+)?commits?\b",
   186	                              sentence, re.I)
   187	            if match:
   188	                add("commit_key", req, sentence, key=match.group(1).title())
   189	                other = _role_of(match.group(2), prescribed) if match.group(2) else None
   190	                if other:
   191	                    add("commit_click_other", req, sentence, role=other)
   192	                if any(re.search(r"\bpersists?\s+after\s+(?:a\s+)?(?:refresh|reload)", item, re.I) for item in sentences):
   193	                    add("commit_persists", req, sentence)
   194	            match = re.search(r"\bpress(?:es|ing)?\s+(Escape|Esc)\s+cancels?\b", sentence, re.I)
   195	            if match:
   196	                add("cancel_key", req, sentence, key="Escape")
   197	            # ---- menus
   198	            match = re.search(r"\bright-click(?:s|ing)?\s+(?:a |an |the )?([a-z ]+?)(?:\s+or\s+(?:a |an |the )?([a-z ]+?))?\s+"
   199	                              r"(?:opens|displays|shows)\s+an?\s+(?:context\s+)?menu", sentence, re.I)
   200	            if match and "menuitem" in prescribed:
   201	                for noun in filter(None, match.groups()):
   202	                    role = _role_of(noun, prescribed)
   203	                    if role:
   204	                        add("context_menu", req, sentence, on=role, item=None)
   205	            match = re.search(r"\b(\w+)\s+context\s+menu\s+provides\s+[^.;]*?\baccessible\s+name\s+\"([^\"]+)\"", sentence, re.I)
   206	            if match and "menuitem" in prescribed:
   207	                on = "gridcell" if match.group(1).lower() == "grid" and "gridcell" in prescribed else _role_of(match.group(1), prescribed)
   208	                if on:
   209	                    add("context_menu", req, sentence, on=on, item=match.group(2))
   210	            # ---- keyboard shortcuts that do what a named control does
   211	            keys = [f"Control+{letter.lower()}" if mod.lower() in ("ctrl", "control") else f"Meta+{letter.lower()}"
   212	                    for mod, letter in _KEY.findall(sentence)]
   213	            if not keys or "same" not in lower:
   214	                continue
   215	            names = _names(sentence.split(_KEY.search(sentence).group(0))[0])
   216	            if names:  # "... menuitem role with the accessible name "X", and Ctrl+V pastes the same ..."
   217	                via = None
   218	                ctx = re.search(r"\b(\w+)\s+context\s+menu\b", sentence, re.I)
   219	                if ctx:
   220	                    via = "gridcell" if ctx.group(1).lower() == "grid" and "gridcell" in prescribed else _role_of(ctx.group(1), prescribed)
   221	                role = "menuitem" if re.search(r"\bmenuitem\b|\bmenu item\b|\bcommand\b", lower) else "button"
   222	                add("key_same_as", req, sentence, key=keys[0], control={"role": role, "name": names[-1]}, before=[],
   223	                    via_context_menu=via, clipboard="clipboard" in lower)
   224	            elif index > 0:  # "The toolbar provides buttons with the accessible names "A" and "B"; K1 and K2 perform the same operations."
   225	                previous = sentences[index - 1]
   226	                named = _names(previous)
   227	                role = "menuitem" if re.search(r"\bmenu\s*items?\b|\bcommands?\b", previous.lower()) else "button"
   228	                for position, key in enumerate(keys[:len(named)]):
   229	                    add("key_same_as", req, previous + " " + sentence, key=key, control={"role": role, "name": named[position]},
   230	                        before=[{"role": role, "name": name} for name in named[:position]], via_context_menu=None,
   231	                        clipboard="clipboard" in lower)
   232	    # checks that need the inline editor or the selection state are only kept when the yaml declares those too
   233	    needs_editor = {"commit_key", "commit_click_other", "cancel_key", "commit_persists"}
   234	    kept = []
   235	    for check in checks:
   236	        if check["kind"] in needs_editor and not editor:
   237	            continue
   238	        if check["kind"] in ("click_select", "drag_select", "selection_persists") and check.get("role", "gridcell") not in selectable:
   239	            continue
   240	        if check["kind"] == "tab_switch" and "tab" not in selectable:
   241	            continue
   242	        if check["kind"] == "key_same_as" and not check["clipboard"] and not editor:
   243	            continue  # the shortcut acts on an edit; without a declared editor the probe cannot make one
   244	        kept.append(check)
   245	    shapes = {role: shape for role, pattern, shape in _NAME_SHAPES
   246	              if any(pattern.search(sentence) for sentence in _SENTENCE.split(whole))}
   247	    return {"entry": _entry(document), "names": shapes, "editor": editor, "checks": kept}
