298	def public_prerequisites(document: Any) -> dict[str, Any]:
299	    """Select bounded GitHub prerequisite flows from the supplied public tree.
300	
301	    The returned configuration is inert for other task families.  Values come
302	    from GIVEN steps rather than hard-coded benchmark fixtures.
303	    """
304	    nodes: list[dict[str, Any]] = []
305	
306	    def visit(node: Any) -> None:
307	        if not isinstance(node, dict):
